{"implementation":"def solve(case):
    """Allocate an exact integer budget using stable coarse-to-fine priorities."""
    import math

    def require_mapping(value, label):
        if not isinstance(value, dict):
            raise ValueError(label + " must be an object")
        return value

    def require_int(value, label):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(label + " must be an integer")
        return value

    def require_importance(value, label):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(label + " must be a finite number")
        if not math.isfinite(value) or value < 0:
            raise ValueError(label + " must be a non-negative finite number")
        return value

    data = require_mapping(case, "case")
    if "segments" not in data or "budget" not in data:
        raise ValueError("case must contain segments and budget")

    segments = data["segments"]
    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a non-empty list")
    budget = require_int(data["budget"], "budget")
    if budget < 0:
        raise ValueError("budget must be non-negative")

    names = []
    importances = []
    allocations = []
    capacities = []
    seen_names = set()
    for index, raw_segment in enumerate(segments):
        segment = require_mapping(raw_segment, "segments[%d]" % index)
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("segments[%d] is missing %s" % (index, field))
        name = segment["name"]
        if not isinstance(name, str) or not name:
            raise ValueError("segments[%d].name must be a non-empty string" % index)
        if name in seen_names:
            raise ValueError("segment names must be unique")
        seen_names.add(name)
        importance = require_importance(segment["importance"], "segments[%d].importance" % index)
        minimum = require_int(segment["minimum"], "segments[%d].minimum" % index)
        capacity = require_int(segment["capacity"], "segments[%d].capacity" % index)
        if minimum < 0 or capacity < 0 or minimum > capacity:
            raise ValueError("each segment requires 0 <= minimum <= capacity")
        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(allocations)
    capacity_total = sum(capacities)
    if budget < minimum_total or budget > capacity_total:
        raise ValueError("budget must be between total minimum and total capacity")

    remaining = budget - minimum_total
    while remaining:
        best = None
        for index in range(len(allocations)):
            if allocations[index] >= capacities[index]:
                continue
            if best is None:
                best = index
                continue
            # Compare importance/(next position) without float division.
            left = importances[index] * (allocations[best] + 1)
            right = importances[best] * (allocations[index] + 1)
            if left > right:
                best = index
        allocations[best] += 1
        remaining -= 1

    name_mapping = {name: allocations[index] for index, name in enumerate(names)}
    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "total": sum(allocations),
    }
"}
